insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"line_msysmv9a_line_msysmv9a_q01_the_these_those_s04","locale":"he","line_order":0,"content":"מצוין! המילה The תעזור לנו לדבר על דברים ספציפיים, נשים אותה לפני המילה שעליה נרצה לדבר\n","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q01_the_these_those_s04_copy","locale":"he","line_order":0,"content":"או! אתם כבר נראים מקצוענים יותר.\nהמילה THESE תעזור לנו עם עצמים רבים שנמצאים בקרבתנו","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q01_the_these_those_s04_copy_copy","locale":"he","line_order":0,"content":"אלופים! עברתם על שלושת המילים, האחרונה THOSE תעזור לנו עם דברים רחוקים...","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q01_the_these_those_start","locale":"he","line_order":0,"content":"אה! לא ראיתי אתכם שם...\nוכן... אני נורא מודאג!","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q01_the_these_those_turn_in","locale":"he","line_order":0,"content":"אני חייב שגם אתם תדעו איך להשתמש במילים, אבל אני לא מסביר את זה נהדר... תעברו אצל ה Farmer!","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q02_farmer_s04","locale":"he","line_order":0,"content":"יפה מאוד, אני רואה שאתם מבינים איך להשתמש ב THE, אבל האם תוכלו להבחין בהבדל הבא?","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q02_farmer_turn_in","locale":"he","line_order":0,"content":"וואו! עכשיו נוכל לדבר שעות על החווה","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q02_the_farmer_start","locale":"he","line_order":0,"content":"שלום חברים! בדיוק מסדר את האספקה לחווה.","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q03_little_girl_start","locale":"he","line_order":0,"content":"היי! באתם ללמוד על מרחקים? זה ממש פשוט!","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q03_little_girl_turn_in","locale":"he","line_order":0,"content":"אני רואה שהבנתם חבר'ה....","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q04_village_head_s05","locale":"he","line_order":0,"content":"אני לא מאמין... יש לכם את כל ה Corn!","line_format":"plain_text"},{"dialogue_key":"line_msysmv9a_line_msysmv9a_q04_village_head_start","locale":"he","line_order":0,"content":"לא ייאמן! כבר חזרתם??","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
